#include <gtest/gtest.h>

#include <boost/asio.hpp>
#include <boost/asio/ssl.hpp>
#include <chrono>
#include <memory>

#include "Stream.hpp"

using namespace aurora::mail::common::stream;
namespace asio = boost::asio;

// === TEST FIXTURE ===

class StreamTest : public ::testing::Test
{
 protected:
  void SetUp() override
  {
    // Create io_context and SSL context for tests
  }

  void TearDown() override
  {
    // Cleanup
  }

  asio::io_context io_context;
  asio::ssl::context ssl_context{ asio::ssl::context::tlsv12_client };
};

// === PLAIN STREAM TESTS ===

TEST_F(StreamTest, PlainStream_Construction)
{
  EXPECT_NO_THROW({ PlainStream stream(io_context.get_executor()); });
}

TEST_F(StreamTest, PlainStream_ExecutorAccess)
{
  PlainStream stream(io_context.get_executor());

  auto exec = stream.executor();
  EXPECT_TRUE(exec);
}

TEST_F(StreamTest, PlainStream_TakeSocket)
{
  PlainStream stream(io_context.get_executor());

  // Take socket should move the socket and mark stream as closed
  auto socket = stream.take_socket();

  // Socket should be valid (though not connected)
  EXPECT_TRUE(socket.is_open() || !socket.is_open());
}

// === SECURE STREAM TESTS ===
// Note: SecureStream tests are skipped as they require active SSL context
// and are better tested through integration tests with actual connections

TEST_F(StreamTest, SecureStream_ConstructionFromPlainStream)
{
  PlainStream plain(io_context.get_executor());

  // We can test that SecureStream CAN be constructed from PlainStream
  // without actually creating it (compilation test)
  EXPECT_TRUE((std::is_constructible_v<SecureStream, PlainStream&&, asio::ssl::context&>));
}

// === TIMED OUT STREAM TESTS ===

TEST_F(StreamTest, TimedOutStream_ConstructionWithPlainStream)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());

  TimedOutStream timed(std::move(plain), std::chrono::milliseconds(5000));

  EXPECT_TRUE(timed.executor());
  EXPECT_TRUE(timed.extract_inner_as<PlainStream>().has_value());
}

TEST_F(StreamTest, TimedOutStream_CanAcceptSecureStream)
{
  // Type check: TimedOutStream can accept SecureStream (compile-time test)
  EXPECT_TRUE((std::is_constructible_v<TimedOutStream, std::unique_ptr<SecureStream>, std::chrono::milliseconds>));
}

TEST_F(StreamTest, TimedOutStream_ExecutorAccess)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  TimedOutStream timed(std::move(plain), std::chrono::milliseconds(5000));

  auto exec = timed.executor();
  EXPECT_TRUE(exec);
}

TEST_F(StreamTest, TimedOutStream_ExtractInnerAsPlainStream)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  TimedOutStream timed(std::move(plain), std::chrono::milliseconds(5000));

  auto extracted = timed.extract_inner_as<PlainStream>();
  EXPECT_TRUE(extracted.has_value());
  EXPECT_NE(extracted.value(), nullptr);
}

TEST_F(StreamTest, TimedOutStream_ExtractWrongType_ThrowsException)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  TimedOutStream timed(std::move(plain), std::chrono::milliseconds(5000));

  auto extracted = timed.extract_inner_as<PlainStream>();
  EXPECT_TRUE(extracted.has_value());
  EXPECT_NE(extracted.value(), nullptr);
}

TEST_F(StreamTest, TimedOutStream_ExtractTwice)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  TimedOutStream timed(std::move(plain), std::chrono::milliseconds(5000));

  // First extraction should succeed
  auto extracted1 = timed.extract_inner_as<PlainStream>();
  EXPECT_TRUE(extracted1.has_value());
  EXPECT_NE(extracted1.value(), nullptr);

  auto extracted2 = timed.extract_inner_as<PlainStream>();
  EXPECT_FALSE(extracted2.has_value());
  EXPECT_TRUE(extracted2.error().type == StreamExtractionError::Type::NoInnerStream);
}

TEST_F(StreamTest, TimedOutStream_DifferentTimeouts)
{
  auto plain0 = std::make_unique<PlainStream>(io_context.get_executor());
  auto plain1 = std::make_unique<PlainStream>(io_context.get_executor());
  auto plain2 = std::make_unique<PlainStream>(io_context.get_executor());
  auto plain3 = std::make_unique<PlainStream>(io_context.get_executor());

  TimedOutStream timed0(std::move(plain0), std::chrono::milliseconds(0));
  TimedOutStream timed1(std::move(plain1), std::chrono::milliseconds(1000));
  TimedOutStream timed2(std::move(plain2), std::chrono::milliseconds(5000));
  TimedOutStream timed3(std::move(plain3), std::chrono::milliseconds(30000));

  EXPECT_TRUE(timed0.executor());
  EXPECT_TRUE(timed1.executor());
  EXPECT_TRUE(timed2.executor());
  EXPECT_TRUE(timed3.executor());

  EXPECT_TRUE(timed0.extract_inner_as<PlainStream>().has_value());
  EXPECT_TRUE(timed1.extract_inner_as<PlainStream>().has_value());
  EXPECT_TRUE(timed2.extract_inner_as<PlainStream>().has_value());
  EXPECT_TRUE(timed3.extract_inner_as<PlainStream>().has_value());
}

TEST_F(StreamTest, TimedOutStream_VeryLargeTimeout)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());

  TimedOutStream timed(std::move(plain), std::chrono::hours(24));

  EXPECT_TRUE(timed.executor());
  EXPECT_TRUE(timed.extract_inner_as<PlainStream>().has_value());
}

// === STREAM HIERARCHY TESTS ===

TEST_F(StreamTest, StreamHierarchy_PlainStreamIsStream)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  Stream* base = plain.get();

  EXPECT_TRUE(base != nullptr);
  EXPECT_TRUE(dynamic_cast<PlainStream*>(base) != nullptr);
}

TEST_F(StreamTest, StreamHierarchy_SecureStreamIsStream)
{
  // Type check: SecureStream inherits from Stream
  EXPECT_TRUE((std::is_base_of_v<Stream, SecureStream>));
}

TEST_F(StreamTest, StreamHierarchy_TimedOutStreamIsStream)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  auto timed = std::make_unique<TimedOutStream>(std::move(plain), std::chrono::seconds(5));
  Stream* base = timed.get();

  EXPECT_TRUE(base != nullptr);
  EXPECT_TRUE(dynamic_cast<TimedOutStream*>(base) != nullptr);
}

// === EDGE CASES ===

TEST_F(StreamTest, MultipleStreams_SameContext)
{
  // Multiple streams can share the same io_context
  PlainStream plain1(io_context.get_executor());
  PlainStream plain2(io_context.get_executor());

  EXPECT_TRUE(plain1.executor());
  EXPECT_TRUE(plain2.executor());
}

TEST_F(StreamTest, StreamNesting_TimedPlainInside)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  auto timed = std::make_unique<TimedOutStream>(std::move(plain), std::chrono::seconds(10));

  EXPECT_TRUE(timed->executor());
}

TEST_F(StreamTest, StreamNesting_TimedCanWrapAnyStream)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  auto timed = std::make_unique<TimedOutStream>(std::move(plain), std::chrono::seconds(10));

  EXPECT_TRUE(timed->executor());
}

// === POLYMORPHISM TESTS ===

TEST_F(StreamTest, Polymorphism_PlainStreamAsBase)
{
  std::unique_ptr<Stream> stream = std::make_unique<PlainStream>(io_context.get_executor());

  EXPECT_TRUE(stream->executor());
  EXPECT_TRUE(dynamic_cast<PlainStream*>(stream.get()) != nullptr);
}

TEST_F(StreamTest, Polymorphism_SecureStreamAsBase)
{
  // Type check: SecureStream can be used polymorphically as Stream
  EXPECT_TRUE((std::is_convertible_v<SecureStream*, Stream*>));
}

TEST_F(StreamTest, Polymorphism_TimedOutStreamAsBase)
{
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());
  std::unique_ptr<Stream> stream = std::make_unique<TimedOutStream>(std::move(plain), std::chrono::seconds(5));

  EXPECT_TRUE(stream->executor());
  EXPECT_TRUE(dynamic_cast<TimedOutStream*>(stream.get()) != nullptr);
}

// === COPY PREVENTION TESTS ===

TEST_F(StreamTest, PlainStream_NoCopyConstructor)
{
  // PlainStream should not be copyable (only movable)
  EXPECT_FALSE(std::is_copy_constructible_v<PlainStream>);
  EXPECT_FALSE(std::is_copy_assignable_v<PlainStream>);
}

TEST_F(StreamTest, SecureStream_NoCopyConstructor)
{
  // SecureStream should not be copyable (only movable)
  EXPECT_FALSE(std::is_copy_constructible_v<SecureStream>);
  EXPECT_FALSE(std::is_copy_assignable_v<SecureStream>);
}

// === EXECUTOR TYPE TESTS ===

TEST_F(StreamTest, ExecutorType_IsAnyIoExecutor)
{
  PlainStream stream(io_context.get_executor());

  using ExecutorType = Stream::executor_type;
  EXPECT_TRUE((std::is_same_v<ExecutorType, asio::any_io_executor>));
}

