// === ADDITIONAL CONSTRUCTION TESTS ===

TEST_F(StreamTest, PlainStream_MultipleInstances)
{
  PlainStream stream1(io_context.get_executor());
  PlainStream stream2(io_context.get_executor());
  PlainStream stream3(io_context.get_executor());

  EXPECT_TRUE(stream1.executor());
  EXPECT_TRUE(stream2.executor());
  EXPECT_TRUE(stream3.executor());
}

TEST_F(StreamTest, SecureStream_TypeProperties)
{
  // Type checks for SecureStream
  EXPECT_FALSE(std::is_copy_constructible_v<SecureStream>);
  EXPECT_FALSE(std::is_copy_assignable_v<SecureStream>);
  EXPECT_TRUE(std::is_destructible_v<SecureStream>);
}

TEST_F(StreamTest, TimedOutStream_NestedExtraction)
{
  // Create a plain stream
  auto plain = std::make_unique<PlainStream>(io_context.get_executor());

  // Wrap it in TimedOutStream
  TimedOutStream timed(std::move(plain), std::chrono::seconds(10));

  // Extract it back
  auto extracted = timed.extract_inner_as<PlainStream>();

  EXPECT_TRUE(extracted.has_value());
  EXPECT_TRUE(extracted.value()->executor());
}
